1	// Package start implements the `worklog start <id>` operation: promoting a
2	// ticket from `## Next` / `## Someday` (or a child of an epic from its notes
3	// file) into `## Now`, with cap enforcement and parent-linkage upkeep.
4	package start
5	
6	import (
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"regexp"
12		"strings"
13	
14		"github.com/prestontallen/ai-devboard/worklog/internal/model"
15		"github.com/prestontallen/ai-devboard/worklog/internal/parse"
16		"github.com/prestontallen/ai-devboard/worklog/internal/reindex"
17		"github.com/prestontallen/ai-devboard/worklog/internal/render"
18	)
19	
20	// Resolution identifies what kind of ID was passed to start.
21	type Resolution int
22	
23	const (
24		ResUnknown Resolution = iota
25		ResStandalone
26		ResChildOfEpic
27		ResEpic
28		ResAlreadyActive
29	)
30	
31	// ResolveResult bundles everything Resolve learned, so Run can branch
32	// without re-doing the lookup work.
33	type ResolveResult struct {
34		Resolution Resolution
35		Block      *model.Block // populated for Standalone, AlreadyActive, Epic, or (synthesized) ChildOfEpic
36		EpicID     string       // parent epic id for ChildOfEpic; self id for Epic
37		ChildLine  string       // raw `- [ ] ...` line text for ChildOfEpic
38		Children   []string     // open child IDs for Epic refusal
39	}
40	
41	// Inputs captures the user's intent for a start call.
42	type Inputs struct {
43		ID         string
44		Repo       string
45		Tags       []string
46		Acceptance string
47	}
48	
49	// Output is the JSON wire shape for the CLI success path.
50	type Output struct {
51		Status  string `json:"status"`
52		ID      string `json:"id"`
53		Title   string `json:"title"`
54		Section string `json:"section"`
55		Parent  string `json:"parent"`
56		// Type is the ticket's block type ("spike", "chore"); empty for an
57		// ordinary ticket. Surfaced so the CLI can mirror it to devboard
58		// without re-parsing WORK.md.
59		Type     string   `json:"type,omitempty"`
60		Started  string   `json:"started"`
61		WorkMD   string   `json:"workMD"`
62		Warnings []string `json:"warnings"`
63	}
64	
65	// Sentinel errors. The CLI wrapper maps these to specific exit codes and
66	// messages; the orchestration layer never speaks UI.
67	var (
68		ErrIDNotFound      = errors.New("ticket ID not found")
69		ErrCapExceeded     = errors.New("## Now is at cap")
70		ErrAlreadyStarted  = errors.New("ticket is already in ## Now")
71		ErrEpicCannotStart = errors.New("epics do not occupy ## Now")
72		// ErrParentEpicGone: the child resolved from a notes file, but its epic
73		// block is no longer in WORK.md (typically archived). Detected before
74		// any mutation so no partial state is written.
75		ErrParentEpicGone = errors.New("parent epic not in WORK.md")
76	)
77	
78	const cap = 5
79	
80	// IndexNotUpdatedWarning is exported so the CLI can tell it apart from other
81	// warnings when deciding which follow-up hint to print.
82	const IndexNotUpdatedWarning = "INDEX.md not updated (deferred to Phase 2B)"
83	
84	// childLineRe matches a checkbox child line in a notes file. The state char
85	// is captured but ignored for matching; only `[ ]` lines represent open
86	// children in practice, but the regex accepts any state so we can detect
87	// "already started elsewhere" scenarios if they ever come up.
88	var childLineRe = regexp.MustCompile(`^- \[[ ~x]\]\s+([a-zA-Z0-9_-]+)(?::\s*(.*))?$`)
89	
90	// openChildLineRe is strictly `- [ ]` lines (open children only).
91	var openChildLineRe = regexp.MustCompile(`^- \[ \]\s+([a-zA-Z0-9_-]+)`)
92	
93	// Resolve inspects the parsed WorkDoc and (if needed) the notes/ directory to
94	// determine what `id` refers to.
95	func Resolve(wd model.Workdir, doc *model.WorkDoc, id string) (ResolveResult, error) {
96		id = strings.ToLower(strings.TrimSpace(id))
97		if id == "" {
98			return ResolveResult{}, fmt.Errorf("empty id")
99		}
100	
101		// Direct block lookup.
102		if block := doc.BlockByID(id); block != nil {
103			switch {
104			case block.Section == model.SectionNow && block.IsActive():
105				return ResolveResult{Resolution: ResAlreadyActive, Block: block}, nil
106			case block.IsEpic():
107				children, err := readEpicChildren(wd, id)
108				if err != nil {
109					return ResolveResult{}, err
110				}
111				return ResolveResult{
112					Resolution: ResEpic,
113					Block:      block,
114					EpicID:     id,
115					Children:   children,
116				}, nil
117			default:
118				return ResolveResult{Resolution: ResStandalone, Block: block}, nil
119			}
120		}
121	
122		// Otherwise scan notes/*.md for a checkbox child matching id.
123		epicID, line, title, err := scanNotesForChild(wd, id)
124		if err != nil {
125			return ResolveResult{}, err
126		}
127		if epicID != "" {
128			return ResolveResult{
129				Resolution: ResChildOfEpic,
130				EpicID:     epicID,
131				ChildLine:  line,
132				Block: &model.Block{
133					ID:     id,
134					Title:  title,
135					Parent: epicID,
136					Type:   model.TypeTicket,
137				},
138			}, nil
139		}
140	
141		return ResolveResult{Resolution: ResUnknown}, nil
142	}
143	
144	// scanNotesForChild walks notes/*.md looking for a checkbox line whose first
145	// token matches id (case-insensitive). Returns (epicID, raw line, title, nil)
146	// on first match; ("", "", "", nil) when not found.
147	func scanNotesForChild(wd model.Workdir, id string) (string, string, string, error) {
148		entries, err := os.ReadDir(wd.NotesDir())
149		if err != nil {
150			if os.IsNotExist(err) {
151				return "", "", "", nil
152			}
153			return "", "", "", err
154		}
155		for _, e := range entries {
156			if e.IsDir() || !strings.HasSuffix(e.Name(), ".md") {
157				continue
158			}
159			epic := strings.TrimSuffix(e.Name(), ".md")
160			path := filepath.Join(wd.NotesDir(), e.Name())
161			data, err := os.ReadFile(path)
162			if err != nil {
163				continue
164			}
165			for _, line := range strings.Split(string(data), "\n") {
166				m := childLineRe.FindStringSubmatch(line)
167				if m == nil {
168					continue
169				}
170				if strings.EqualFold(m[1], id) {
171					return epic, line, strings.TrimSpace(m[2]), nil
172				}
173			}
174		}
175		return "", "", "", nil
176	}
177	
178	// readEpicChildren reads notes/<epicID>.md and returns the open child IDs in
179	// document order.
180	func readEpicChildren(wd model.Workdir, epicID string) ([]string, error) {
181		data, err := os.ReadFile(wd.NotesFile(epicID))
182		if err != nil {
183			if os.IsNotExist(err) {
184				return nil, nil
185			}
186			return nil, err
187		}
188		var out []string
189		for _, line := range strings.Split(string(data), "\n") {
190			if m := openChildLineRe.FindStringSubmatch(line); m != nil {
191				out = append(out, m[1])
192			}
193		}
194		return out, nil
195	}
196	
197	// Run is the orchestration entry-point. It parses WORK.md, resolves the id,
198	// applies the appropriate mutation, and writes the result atomically.
199	func Run(wd model.Workdir, in Inputs, today string) (Output, error) {
200		doc, err := parse.File(wd.WorkMD())
201		if err != nil {
202			return Output{}, err
203		}
204	
205		res, err := Resolve(wd, doc, in.ID)
206		if err != nil {
207			return Output{}, err
208		}
209	
210		switch res.Resolution {
211		case ResUnknown:
212			return Output{}, fmt.Errorf("%w: %q", ErrIDNotFound, in.ID)
213		case ResAlreadyActive:
214			return Output{}, fmt.Errorf("%w: %q is already in ## Now", ErrAlreadyStarted, in.ID)
215		case ResEpic:
216			inNow := nowIDSet(doc)
217			var startable []string
218			for _, c := range res.Children {
219				if !inNow[strings.ToLower(c)] {
220					startable = append(startable, c)
221				}
222			}
223			return Output{}, fmt.Errorf("%w; epic %q %s",
224				ErrEpicCannotStart, in.ID, describeChildren(startable, res.Children))
225		}
226	
227		// Cap check. The check only applies when the operation would INCREASE
228		// the count in ## Now (i.e. block isn't already there).
229		nowCount, nowIDs := nowSnapshot(doc)
230		movingFromNow := res.Resolution == ResStandalone &&
231			res.Block.Section == model.SectionNow
232		if !movingFromNow && nowCount >= cap {
233			return Output{}, fmt.Errorf("%w (%d/%d); current Now: %s",
234				ErrCapExceeded, nowCount, cap, strings.Join(nowIDs, ", "))
235		}
236	
237		var (
238			newLines  []string
239			title     string
240			parent    string
241			blockType string
242		)
243	
244		switch res.Resolution {
245		case ResStandalone:
246			title = res.Block.Title
247			parent = res.Block.Parent
248			blockType = string(res.Block.Type)
249			afterRemove, src, err := render.RemoveBlock(doc, in.ID)
250			if err != nil {
251				return Output{}, err
252			}
253			// Re-parse so line numbers are accurate for AppendToSection.
254			afterDoc, err := parse.Bytes(doc.Path, []byte(strings.Join(afterRemove, "\n")))
255			if err != nil {
256				return Output{}, err
257			}
258			blockLines := render.FormatTicketBlock(render.BlockOptions{
259				Title:      src.Title,
260				ID:         src.ID,
261				Type:       string(src.Type),
262				Parent:     src.Parent,
263				Repo:       coalesceStr(in.Repo, src.Repo),
264				Tags:       coalesceTags(in.Tags, src.Tags),
265				Started:    today,
266				PR:         src.PR,
267				Files:      src.Files,
268				Acceptance: coalesceStr(in.Acceptance, src.Acceptance),
269				NotesRef:   src.NotesRef,
270				Status:     src.Status,
271				State:      model.StateActive,
272			})
273			final, err := render.AppendToSection(afterDoc, model.SectionNow, blockLines)
274			if err != nil {
275				return Output{}, err
276			}
277			newLines = final
278	
279		case ResChildOfEpic:
280			// The child came from a notes-file scan; the epic block itself may
281			// be gone (archived epics keep their notes file as history). Refuse
282			// with a clear cause before any mutation.
283			if doc.BlockByID(res.EpicID) == nil {
284				hint := reindex.ArchivedHint(wd.ArchiveDir(), res.EpicID)
285				if hint == "" {
286					hint = "not found and not in the archive"
287				}
288				return Output{}, fmt.Errorf("%w: %q %s; archived epics cannot take new work",
289					ErrParentEpicGone, res.EpicID, hint)
290			}
291			title = res.Block.Title
292			parent = res.EpicID
293			blockLines := render.FormatTicketBlock(render.BlockOptions{
294				Title:      title,
295				ID:         in.ID,
296				Parent:     res.EpicID,
297				Repo:       in.Repo,
298				Tags:       in.Tags,
299				Acceptance: in.Acceptance,
300				Started:    today,
301				State:      model.StateActive,
302			})
303			afterAppend, err := render.AppendToSection(doc, model.SectionNow, blockLines)
304			if err != nil {
305				return Output{}, err
306			}
307			// Re-parse so UpdateEpicActiveChildren sees up-to-date line numbers.
308			afterDoc, err := parse.Bytes(doc.Path, []byte(strings.Join(afterAppend, "\n")))
309			if err != nil {
310				return Output{}, err
311			}
312			final, err := render.UpdateEpicActiveChildren(afterDoc, res.EpicID, in.ID)
313			if err != nil {
314				return Output{}, err
315			}
316			newLines = final
317		}
318	
319		if err := render.WriteAtomic(wd.WorkMD(), newLines); err != nil {
320			return Output{}, err
321		}
322	
323		return Output{
324			Status:   "started",
325			ID:       in.ID,
326			Title:    title,
327			Section:  "Now",
328			Parent:   parent,
329			Type:     blockType,
330			Started:  today,
331			WorkMD:   wd.WorkMD(),
332			Warnings: []string{IndexNotUpdatedWarning},
333		}, nil
334	}
335	
336	// nowIDSet returns the set of lowercase block IDs currently in ## Now.
337	func nowIDSet(doc *model.WorkDoc) map[string]bool {
338		out := map[string]bool{}
339		if now := doc.Section(model.SectionNow); now != nil {
340			for _, b := range now.Blocks {
341				if b.ID != "" {
342					out[strings.ToLower(b.ID)] = true
343				}
344			}
345		}
346		return out
347	}
348	
349	// describeChildren composes the human-readable suffix for an epic-refusal
350	// error. Prefers listing children that aren't already in flight.
351	func describeChildren(startable, allOpen []string) string {
352		switch {
353		case len(startable) > 0:
354			return "has startable children: " + strings.Join(startable, ", ")
355		case len(allOpen) > 0:
356			return "has no startable children (all in progress)"
357		default:
358			return "has no open children"
359		}
360	}
361	
362	func nowSnapshot(doc *model.WorkDoc) (int, []string) {
363		now := doc.Section(model.SectionNow)
364		if now == nil {
365			return 0, nil
366		}
367		ids := make([]string, 0, len(now.Blocks))
368		for _, b := range now.Blocks {
369			if b.ID != "" {
370				ids = append(ids, b.ID)
371			}
372		}
373		return len(now.Blocks), ids
374	}
375	
376	func coalesceStr(override, def string) string {
377		if override != "" {
378			return override
379		}
380		return def
381	}
382	
383	func coalesceTags(override, def []string) []string {
384		if override != nil {
385			return override
386		}
387		return def
388	}
