1	// Package devboard writes devboard task files — the live-telemetry YAML
2	// rendered by the devboard dashboard (see devboard/schema.md at the repo
3	// root). Worklog is the privileged writer of these files, never a required
4	// one: everything here is a silent no-op when the devboard data dir does
5	// not exist, and hand-written schema-valid files remain fully supported.
6	//
7	// Ownership rule (schema.md): every shared field has exactly one author;
8	// mirroring flows worklog→devboard only.
9	package devboard
10	
11	import (
12		"errors"
13		"fmt"
14		"os"
15		"os/exec"
16		"path/filepath"
17		"strings"
18		"time"
19	
20		"gopkg.in/yaml.v3"
21	
22		"github.com/prestontallen/ai-devboard/worklog/internal/lockfile"
23	)
24	
25	// Schema mirror of devboard/schema.md v1. Extra preserves unknown
26	// top-level fields across read-modify-write cycles (comments are not
27	// preserved — documented limitation).
28	type Task struct {
29		Schema int    `yaml:"schema"`
30		Title  string `yaml:"title,omitempty"`
31		// "epic" marks an epic container; "spike" marks investigation-first
32		// work, which the UI renders on a short phase track.
33		Type       string        `yaml:"type,omitempty"`
34		Branch     string        `yaml:"branch,omitempty"`
35		Session    string        `yaml:"session,omitempty"`
36		Worklog    string        `yaml:"worklog,omitempty"`
37		Tier       *int          `yaml:"tier,omitempty"`
38		Complexity string        `yaml:"complexity,omitempty"` // low|medium|high; throttles fan-out
39		Phase      string        `yaml:"phase,omitempty"`
40		Plan       []PlanItem    `yaml:"plan,omitempty"`
41		Score      []ScoreItem   `yaml:"scorecard,omitempty"`
42		Decision   []Decision    `yaml:"decisions,omitempty"`
43		Code       []CodeRef     `yaml:"code,omitempty"`
44		NeedsYou   []NeedsItem   `yaml:"needs_you,omitempty"`
45		WaitingOn  []WaitingItem `yaml:"waiting_on,omitempty"`
46		Links      []Link        `yaml:"links,omitempty"`
47		// Children carries one entry per child ticket when Type == "epic". An
48		// epic file's own Branch/Session/Phase/Plan/Score/Decision/Code/
49		// NeedsYou/WaitingOn/Links are unused — that in-flight detail lives
50		// per child here instead, since more than one child can be active in
51		// ## Now at once and a single shared surface would let them overwrite
52		// each other.
53		Children []ChildEntry   `yaml:"children,omitempty"`
54		Extra    map[string]any `yaml:",inline"`
55	}
56	
57	// Child state values for ChildEntry.State.
58	const (
59		ChildPending = "pending"
60		ChildActive  = "active"
61		ChildDone    = "done"
62	)
63	
64	// ChildEntry is one child ticket's roster row plus its own in-flight detail
65	// — the same shape a standalone ticket file carries, nested instead of
66	// shared, so concurrently active children never collide.
67	type ChildEntry struct {
68		ID         string        `yaml:"id"`
69		Title      string        `yaml:"title,omitempty"`
70		State      string        `yaml:"state"` // pending|active|done
71		Branch     string        `yaml:"branch,omitempty"`
72		Session    string        `yaml:"session,omitempty"`
73		Tier       *int          `yaml:"tier,omitempty"`
74		Complexity string        `yaml:"complexity,omitempty"`
75		Phase      string        `yaml:"phase,omitempty"`
76		Plan       []PlanItem    `yaml:"plan,omitempty"`
77		Score      []ScoreItem   `yaml:"scorecard,omitempty"`
78		Decision   []Decision    `yaml:"decisions,omitempty"`
79		Code       []CodeRef     `yaml:"code,omitempty"`
80		NeedsYou   []NeedsItem   `yaml:"needs_you,omitempty"`
81		WaitingOn  []WaitingItem `yaml:"waiting_on,omitempty"`
82		Links      []Link        `yaml:"links,omitempty"`
83	}
84	
85	// ChildIdentity is the roster input to SyncEpicRoster: just enough to
86	// place a child on the epic card, sourced from notes/<epicID>.md and
87	// WORK.md's Active children — never the child's in-flight detail, which
88	// SyncEpicRoster must not disturb.
89	type ChildIdentity struct {
90		ID    string
91		Title string
92		State string // pending|active|done
93	}
94	
95	type PlanItem struct {
96		Text  string `yaml:"text"`
97		State string `yaml:"state"` // pending|in_progress|done|blocked
98	}
99	
100	type ScoreItem struct {
101		Text   string `yaml:"text"`
102		Verify string `yaml:"verify,omitempty"`
103		Status string `yaml:"status"` // pending|pass|fail
104	}
105	
106	type Decision struct {
107		What string `yaml:"what"`
108		Why  string `yaml:"why,omitempty"`
109		When string `yaml:"when,omitempty"`
110	}
111	
112	type CodeRef struct {
113		File    string `yaml:"file"`
114		Lines   string `yaml:"lines,omitempty"`
115		Lang    string `yaml:"lang,omitempty"`
116		Note    string `yaml:"note,omitempty"`
117		Snippet string `yaml:"snippet,omitempty"`
118	}
119	
120	type NeedsItem struct {
121		Type   string `yaml:"type,omitempty"` // question|checkpoint
122		Text   string `yaml:"text"`
123		Detail string `yaml:"detail,omitempty"`
124	}
125	
126	type Link struct {
127		Label string `yaml:"label,omitempty"`
128		URL   string `yaml:"url"`
129	}
130	
131	// WaitingItem is a question blocked on an EXTERNAL party — another team or
132	// person, expected to sit for days. Distinct from NeedsItem (blocked on the
133	// task's own human, resolvable in minutes).
134	type WaitingItem struct {
135		Text   string `yaml:"text"`
136		Who    string `yaml:"who"`             // who owes the answer; required
137		Asked  string `yaml:"asked,omitempty"` // YYYY-MM-DD; age renders from this
138		Link   string `yaml:"link,omitempty"`  // where it was asked
139		Detail string `yaml:"detail,omitempty"`
140	}
141	
142	// CloseWaitingOn converts every remaining waiting_on entry into an
143	// "unanswered at close" decision and clears the list, so closing a task
144	// never silently drops an outstanding question. Shared by the ticketed
145	// done path (OnDone) and the ticketless CLI path (waiting-on resolve all).
146	func CloseWaitingOn(t *Task, when string) {
147		for _, w := range t.WaitingOn {
148			t.Decision = append(t.Decision, Decision{
149				What: "unanswered at close: " + w.Text + " (" + w.Who + ")",
150				When: when,
151			})
152		}
153		t.WaitingOn = nil
154	}
155	
156	// DataDir returns the devboard data directory: $DEVBOARD_DATA, defaulting
157	// to ~/.local/share/devboard.
158	func DataDir() string {
159		if d := os.Getenv("DEVBOARD_DATA"); d != "" {
160			return d
161		}
162		home, err := os.UserHomeDir()
163		if err != nil {
164			return ""
165		}
166		return filepath.Join(home, ".local", "share", "devboard")
167	}
168	
169	// Enabled reports whether the data dir exists. Callers must treat a false
170	// result as "do nothing, succeed" — devboard is opt-in by dir presence.
171	func Enabled() bool {
172		d := DataDir()
173		if d == "" {
174			return false
175		}
176		fi, err := os.Stat(d)
177		return err == nil && fi.IsDir()
178	}
179	
180	// Find locates an existing task file <data>/<repo>/<slug>.{yaml,yml} across
181	// all repo groups. Returns "" (no error) when absent.
182	func Find(slug string) (string, error) {
183		root := DataDir()
184		entries, err := os.ReadDir(root)
185		if err != nil {
186			return "", err
187		}
188		for _, e := range entries {
189			if !e.IsDir() || strings.HasPrefix(e.Name(), ".") {
190				continue
191			}
192			for _, ext := range []string{".yaml", ".yml"} {
193				p := filepath.Join(root, e.Name(), slug+ext)
194				if fi, err := os.Stat(p); err == nil && fi.Mode().IsRegular() {
195					return p, nil
196				}
197			}
198		}
199		return "", nil
200	}
201	
202	// List returns every task file path grouped under the data dir.
203	func List() ([]string, error) {
204		root := DataDir()
205		entries, err := os.ReadDir(root)
206		if err != nil {
207			return nil, err
208		}
209		var out []string
210		for _, e := range entries {
211			if !e.IsDir() || strings.HasPrefix(e.Name(), ".") {
212				continue
213			}
214			files, err := os.ReadDir(filepath.Join(root, e.Name()))
215			if err != nil {
216				continue
217			}
218			for _, f := range files {
219				name := strings.ToLower(f.Name())
220				if f.Type().IsRegular() && (strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")) {
221					out = append(out, filepath.Join(root, e.Name(), f.Name()))
222				}
223			}
224		}
225		return out, nil
226	}
227	
228	// RepoName derives the grouping directory for new task files: the basename
229	// of the repository, falling back to the cwd basename outside a repo.
230	//
231	// Resolution goes through the *common* git dir rather than the worktree
232	// root. `git rev-parse --show-toplevel` answers with the linked worktree's
233	// own path, so every task file created from a worktree used to be filed
234	// under a group named after the worktree instead of the repo — silently, in
235	// a directory that only ever held that one file.
236	func RepoName() string {
237		if name := repoNameFromCommonDir(); name != "" {
238			return name
239		}
240		// Older git has no --path-format (added in 2.31). Fall back to the
241		// worktree root, which is correct everywhere except inside a linked
242		// worktree — i.e. those users keep the old behavior rather than gaining
243		// a new failure.
244		if out, err := exec.Command("git", "rev-parse", "--show-toplevel").Output(); err == nil {
245			if top := strings.TrimSpace(string(out)); top != "" {
246				return filepath.Base(top)
247			}
248		}
249		wd, err := os.Getwd()
250		if err != nil {
251			return "unknown"
252		}
253		return filepath.Base(wd)
254	}
255	
256	// repoNameFromCommonDir resolves the repository name via the common git dir,
257	// which points at the main repository from anywhere — main checkout, linked
258	// worktree, or any subdirectory of either. Returns "" when git can't answer,
259	// leaving the caller to fall back.
260	func repoNameFromCommonDir() string {
261		out, err := exec.Command("git", "rev-parse", "--path-format=absolute", "--git-common-dir").Output()
262		if err != nil {
263			return ""
264		}
265		dir := strings.TrimSpace(string(out))
266		if dir == "" || !filepath.IsAbs(dir) {
267			return ""
268		}
269		dir = filepath.Clean(dir)
270	
271		// Normal repo: the common dir is <root>/.git, so the repo is its parent.
272		if filepath.Base(dir) == ".git" {
273			return filepath.Base(filepath.Dir(dir))
274		}
275		// Bare repo: the common dir *is* the repository (e.g. …/foo.git).
276		return strings.TrimSuffix(filepath.Base(dir), ".git")
277	}
278	
279	// PendingNewGroup returns the repo group name when devboard is enabled and
280	// that group has no directory yet — i.e. the next task file written will
281	// create it. Empty otherwise.
282	//
283	// A brand-new group is usually just the first ticket in a new repo, but it is
284	// also exactly what a misresolved repo name looks like. The two are
285	// indistinguishable here, so this reports rather than decides: callers surface
286	// it and let the human notice a name that isn't their repo.
287	func PendingNewGroup() string {
288		if !Enabled() {
289			return ""
290		}
291		repo := RepoName()
292		if repo == "" {
293			return ""
294		}
295		if fi, err := os.Stat(filepath.Join(DataDir(), repo)); err == nil && fi.IsDir() {
296			return ""
297		}
298		return repo
299	}
300	
301	// gitBranch returns the current branch name, or "" outside a repo.
302	func gitBranch() string {
303		out, err := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD").Output()
304		if err != nil {
305			return ""
306		}
307		return strings.TrimSpace(string(out))
308	}
309	
310	// Mutate performs a locked, atomic read-modify-write of the task file at
311	// path. When the file is absent it starts from an empty schema-1 task.
312	// A file that exists but fails to parse aborts before fn runs, leaving the
313	// file byte-identical.
314	func Mutate(path string, fn func(*Task) error) error {
315		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
316			return err
317		}
318		unlock, err := lockfile.Acquire(path + ".lock")
319		if err != nil {
320			return err
321		}
322		defer unlock()
323	
324		t := &Task{Schema: 1}
325		raw, err := os.ReadFile(path)
326		switch {
327		case err == nil:
328			if uerr := yaml.Unmarshal(raw, t); uerr != nil {
329				return fmt.Errorf("devboard: %s is not valid YAML (file left untouched): %w", path, uerr)
330			}
331			if t.Schema == 0 {
332				t.Schema = 1
333			}
334		case errors.Is(err, os.ErrNotExist):
335			// fresh task
336		default:
337			return err
338		}
339	
340		if err := fn(t); err != nil {
341			return err
342		}
343	
344		out, err := yaml.Marshal(t)
345		if err != nil {
346			return err
347		}
348		tmp, err := os.CreateTemp(filepath.Dir(path), ".devboard-*")
349		if err != nil {
350			return err
351		}
352		tmpName := tmp.Name()
353		if _, err := tmp.Write(out); err != nil {
354			tmp.Close()
355			os.Remove(tmpName)
356			return err
357		}
358		if err := tmp.Close(); err != nil {
359			os.Remove(tmpName)
360			return err
361		}
362		if err := os.Rename(tmpName, path); err != nil {
363			os.Remove(tmpName)
364			return err
365		}
366		return nil
367	}
368	
369	// pathFor returns the existing file for slug, or the creation path in the
370	// current repo group when none exists.
371	func pathFor(slug string) (string, error) {
372		if p, err := Find(slug); err != nil || p != "" {
373			return p, err
374		}
375		return filepath.Join(DataDir(), RepoName(), slug+".yaml"), nil
376	}
377	
378	// today is stubbed in tests.
379	var today = func() string { return time.Now().Format("2006-01-02") }
380	
381	// --- worklog lifecycle side effects -----------------------------------
382	// All three are silent no-ops when devboard is not Enabled. Errors are
383	// returned for the caller to WARN on — a devboard failure must never fail
384	// the worklog operation itself.
385	
386	// OnStart guarantees a task file exists for the started ticket, carrying
387	// identity fields. It does NOT set phase — phases are agent-driven.
388	//
389	// blockType mirrors the ticket's WORK.md Type ("spike", "chore"); empty for
390	// an ordinary ticket. Like title, it is identity rather than workflow state
391	// — the board reads it to pick the short research track for a spike.
392	func OnStart(id, title, blockType string) error {
393		if !Enabled() {
394			return nil
395		}
396		path, err := pathFor(id)
397		if err != nil {
398			return err
399		}
400		return Mutate(path, func(t *Task) error {
401			created := t.Title == "" && t.Worklog == ""
402			// "epic" belongs to SyncEpicRoster; a start must never overwrite it.
403			if blockType != "" && blockType != "ticket" && t.Type != "epic" {
404				t.Type = blockType
405			}
406			if title != "" {
407				t.Title = title
408			}
409			t.Worklog = id
410			if s := os.Getenv("CLAUDE_CODE_SESSION_ID"); s != "" {
411				t.Session = s
412			}
413			if created {
414				if b := gitBranch(); b != "" {
415					t.Branch = b
416				}
417			}
418			return nil
419		})
420	}
421	
422	// OnDone marks the task done and clears the attention queue. No-op when no
423	// task file exists for the ticket.
424	func OnDone(id string) error {
425		if !Enabled() {
426			return nil
427		}
428		path, err := Find(id)
429		if err != nil || path == "" {
430			return err
431		}
432		return Mutate(path, func(t *Task) error {
433			t.Phase = "done"
434			t.NeedsYou = nil
435			CloseWaitingOn(t, today())
436			return nil
437		})
438	}
439	
440	// SyncEpicRoster ensures an epic's task file carries Type "epic", its
441	// title, and an up-to-date roster: every entry in roster is upserted by
442	// ID, updating only Title/State (identity) — an existing child's
443	// in-flight detail (Branch/Phase/Plan/Score/... , set separately via
444	// MutateChild) is never touched. Children not present in roster are left
445	// as-is rather than pruned, since the notes-file scan this is sourced
446	// from is expected to be append-only. Silent no-op when devboard is
447	// disabled, same contract as OnStart/OnDone.
448	func SyncEpicRoster(epicID, epicTitle string, roster []ChildIdentity) error {
449		if !Enabled() {
450			return nil
451		}
452		path, err := pathFor(epicID)
453		if err != nil {
454			return err
455		}
456		return Mutate(path, func(t *Task) error {
457			t.Type = "epic"
458			if epicTitle != "" {
459				t.Title = epicTitle
460			}
461			t.Worklog = epicID
462			for _, ci := range roster {
463				if idx := indexOfChild(t.Children, ci.ID); idx >= 0 {
464					if ci.Title != "" {
465						t.Children[idx].Title = ci.Title
466					}
467					t.Children[idx].State = ci.State
468				} else {
469					t.Children = append(t.Children, ChildEntry{ID: ci.ID, Title: ci.Title, State: ci.State})
470				}
471			}
472			return nil
473		})
474	}
475	
476	// MutateChild performs a locked, atomic read-modify-write of one child's
477	// entry within an epic's task file at path, identified by childID. A
478	// child not yet on the roster is appended with State ChildPending before
479	// fn runs — the roster sync from a real ticket start will correct its
480	// identity later. Callers gate Enabled()/taskDisabled themselves, matching
481	// Mutate's contract.
482	func MutateChild(path, childID string, fn func(*ChildEntry) error) error {
483		return Mutate(path, func(t *Task) error {
484			idx := indexOfChild(t.Children, childID)
485			if idx < 0 {
486				t.Children = append(t.Children, ChildEntry{ID: childID, State: ChildPending})
487				idx = len(t.Children) - 1
488			}
489			return fn(&t.Children[idx])
490		})
491	}
492	
493	// indexOfChild returns the index of the child with the given ID
494	// (case-insensitive, matching worklog's ID normalization elsewhere), or -1.
495	func indexOfChild(children []ChildEntry, id string) int {
496		for i, c := range children {
497			if strings.EqualFold(c.ID, id) {
498				return i
499			}
500		}
501		return -1
502	}
503	
504	// OnPR sets (or clears, url=="") the PR link on the ticket's task file.
505	// No-op when no task file exists.
506	func OnPR(id, url string) error {
507		if !Enabled() {
508			return nil
509		}
510		path, err := Find(id)
511		if err != nil || path == "" {
512			return err
513		}
514		return Mutate(path, func(t *Task) error {
515			kept := t.Links[:0]
516			for _, l := range t.Links {
517				if l.Label != "PR" {
518					kept = append(kept, l)
519				}
520			}
521			t.Links = kept
522			if url != "" {
523				t.Links = append(t.Links, Link{Label: "PR", URL: url})
524			}
525			return nil
526		})
527	}
